+// Virtual time verifies that resetting the timer preserves every retry delay.
+func TestRetryTimerDelays(t *testing.T) {
+	for _, fixed := range []bool{false, true} {
+		t.Run(map[bool]string{false: "backoff", true: "fixed"}[fixed], func(t *testing.T) {
+			synctest.Test(t, func(t *testing.T) {
+				q, err := NewQueue(WithWorker(NewRing()), WithLogger(NewEmptyLogger()))
+				require.NoError(t, err)
+				t.Cleanup(q.Release)
+				var attempts int
+				opts := job.AllowOption{
+					RetryCount: job.Int64(3),
+					RetryMin:   job.Time(10 * time.Millisecond),
+					RetryMax:   job.Time(time.Second),
+				}
+				want := 70 * time.Millisecond // 10 + 20 + 40
+				if fixed {
+					opts.RetryDelay = job.Time(10 * time.Millisecond)
+					want = 30 * time.Millisecond
+				}
+				m := job.NewTask(func(context.Context) error {
+					attempts++
+					if attempts < 4 {
+						return errors.New("retry")
+					}
+					return nil
+				}, opts)
+				start := time.Now()
+				require.NoError(t, q.handle(&m))
+				require.Equal(t, 4, attempts)
+				require.Equal(t, want, time.Since(start))
+			})
+		})
+	}
+}
